// Runtime resolver με memoization
const _movesCache = {};
function getMovesForPokemon(id) {
  id = String(id);
  if (_movesCache[id]) return _movesCache[id];

  const entry = MOVES_BY_POKEMON_RAW[id];
  if (!entry) return [];

  let list;
  if (Array.isArray(entry)) {
    list = entry.slice();
  } else {
    const parentMoves = getMovesForPokemon(entry.from);
    const removeSet = entry.remove ? new Set(entry.remove) : null;
    list = removeSet ? parentMoves.filter(m => !removeSet.has(m)) : parentMoves.slice();
    list.push(...entry.add);
  }
  _movesCache[id] = list;
  return list;
}
